def find_longest_suffix_subgroup(n, strings):
    suffix_map = {}
    for i, s in enumerate(strings):
        for j in range(1, len(s) + 1):
            suffix = s[-j:]
            if suffix not in suffix_map:
                suffix_map[suffix] = []
            suffix_map[suffix].append(i + 1)

    max_length = 0
    for suffix, indices in suffix_map.items():
        if len(indices) > max_length:
            max_length = len(indices)

    return max_length

